// PostProblem defines model for PostProblem.
type PostProblem struct {
	// Code - `empty_text` — в посте нет текста;
	// - `body_too_long` — текст с разметкой и UTM-метками длиннее 3800 знаков;
	// - `too_many_media` — изображений больше предела альбома;
	// - `link_not_https` — ссылка не `https://`;
	// - `media_required_for_token` — `token_carrier = media`, а изображений нет;
	// - `link_required_for_token` — `token_position = link`, а ссылок нет;
	// - `media_processing` — изображения с плашкой или их копии ещё строятся;
	// - `requisites_missing` — у организации нет названия или ИНН.
	Code    PostProblemCode `json:"code"`
	Message string          `json:"message"`
}

// PostProblemCode - `empty_text` — в посте нет текста;
// - `body_too_long` — текст с разметкой и UTM-метками длиннее 3800 знаков;
// - `too_many_media` — изображений больше предела альбома;
// - `link_not_https` — ссылка не `https://`;
// - `media_required_for_token` — `token_carrier = media`, а изображений нет;
// - `link_required_for_token` — `token_position = link`, а ссылок нет;
// - `media_processing` — изображения с плашкой или их копии ещё строятся;
// - `requisites_missing` — у организации нет названия или ИНН.
type PostProblemCode string

